from __future__ import annotations
from itertools import combinations, product
from typing import Optional

Edge = tuple[int, int]
BranchModel = tuple[frozenset[int], ...]

def adjacent(edges: set[Edge], u: int, v: int) -> bool:
    return (min(u, v), max(u, v)) in edges and u != v

def connected(branch: frozenset[int], edges: set[Edge]) -> bool:
    if not branch:
        return False
    seen = {next(iter(branch))}
    stack = list(seen)
    while stack:
        u = stack.pop()
        for v in branch - seen:
            if adjacent(edges, u, v):
                seen.add(v)
                stack.append(v)
    return seen == set(branch)

def find_complete_minor(n: int, raw_edges: set[Edge], t: int) -> Optional[BranchModel]:
    edges = {(min(u, v), max(u, v)) for u, v in raw_edges if u != v}
    if t == 0:
        return tuple()
    if t < 0 or t > n:
        return None
    for labels in product(range(t + 1), repeat=n):
        branches = tuple(frozenset(v for v in range(n) if labels[v] == i)
                         for i in range(1, t + 1))
        if any(not b for b in branches):
            continue
        if [min(b) for b in branches] != sorted(min(b) for b in branches):
            continue
        if not all(connected(b, edges) for b in branches):
            continue
        if not all(any(adjacent(edges, u, v) for u in branches[i] for v in branches[j])
                   for i, j in combinations(range(t), 2)):
            continue
        return branches
    return None

